-- ----------------------------------------------------------------------
-- user  [User Management]
-- Registered account. Email and username are unique; passwords are stored only as hashes. Email is immutable after registration.
--   APP RULE: email cannot be changed after registration (reject UPDATE of email in the backend).
-- ----------------------------------------------------------------------
CREATE TABLE `user` (
  `user_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `full_name` VARCHAR(100) NOT NULL,
  `username` VARCHAR(30) NOT NULL,
  `email` VARCHAR(255) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `profile_picture_url` VARCHAR(2048) NULL,
  `description` TEXT NULL,
  `learning_language` ENUM('ENGLISH','KOREAN') NULL,
  `account_role` ENUM('USER','SUPERADMIN') NOT NULL DEFAULT 'USER',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `pk_user` PRIMARY KEY (`user_id`),
  CONSTRAINT `uq_user_username` UNIQUE (`username`),
  CONSTRAINT `uq_user_email` UNIQUE (`email`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- user_preferences  [User Management]
-- 1:1 extension of user holding the two independent language settings. Row created in the same transaction as the user.
--   APP RULE: Insert the preferences row together with the user row (exactly one per user).
-- ----------------------------------------------------------------------
CREATE TABLE `user_preferences` (
  `user_id` BIGINT UNSIGNED NOT NULL,
  `interface_language` ENUM('ENGLISH','KOREAN') NOT NULL DEFAULT 'ENGLISH',
  `translation_target_language` ENUM('ENGLISH','KOREAN') NOT NULL DEFAULT 'KOREAN',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `pk_user_preferences` PRIMARY KEY (`user_id`),
  CONSTRAINT `fk_user_preferences_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- room  [Rooms and Membership]
-- Private room. All rooms are private: there is no visibility column. owner_user_id is the single source of truth for the owner.
--   APP RULE: Max 10 rooms per owner (count before INSERT, inside a transaction).
--   APP RULE: Creating a room also inserts the owner's room_membership row with role OWNER.
-- ----------------------------------------------------------------------
CREATE TABLE `room` (
  `room_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `owner_user_id` BIGINT UNSIGNED NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `description` TEXT NOT NULL,
  `cover_image_url` VARCHAR(2048) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `pk_room` PRIMARY KEY (`room_id`),
  CONSTRAINT `fk_room_owner_user_id` FOREIGN KEY (`owner_user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- room_membership  [Rooms and Membership]
-- Current members of a room (junction user <-> room). Rows are deleted when a user leaves or is removed; no history is kept.
--   APP RULE: Max 40 memberships per room including the owner (SELECT ... FOR UPDATE on the room, count, then insert).
--   APP RULE: Only OWNER/ADMIN can remove members; any member can leave (delete their own row).
--   APP RULE: The OWNER membership must belong to room.owner_user_id and cannot be removed; the owner deletes the room instead of leaving it.
-- ----------------------------------------------------------------------
CREATE TABLE `room_membership` (
  `room_id` BIGINT UNSIGNED NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `membership_role` ENUM('OWNER','ADMIN','MEMBER') NOT NULL DEFAULT 'MEMBER',
  `joined_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `owner_flag` TINYINT GENERATED ALWAYS AS (IF(membership_role = 'OWNER', 1, NULL)) STORED NULL,
  CONSTRAINT `pk_room_membership` PRIMARY KEY (`room_id`, `user_id`),
  CONSTRAINT `uq_room_membership_one_owner` UNIQUE (`room_id`, `owner_flag`),
  INDEX `idx_room_membership_user` (`user_id`),
  CONSTRAINT `fk_room_membership_room_id` FOREIGN KEY (`room_id`) REFERENCES `room` (`room_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_room_membership_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- room_invitation  [Rooms and Membership]
-- Expiring invitation link. The URL (and its QR code) carries a random token; only its SHA-256 hash is stored.
--   APP RULE: A link is valid only if expires_at > NOW(); joining also re-checks the 40-member limit.
--   APP RULE: Only OWNER/ADMIN may create invitations (see open questions).
-- ----------------------------------------------------------------------
CREATE TABLE `room_invitation` (
  `invitation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` BIGINT UNSIGNED NOT NULL,
  `created_by_user_id` BIGINT UNSIGNED NOT NULL,
  `invited_user_id` BIGINT UNSIGNED NULL,
  `token_hash` CHAR(64) NOT NULL,
  `expires_at` DATETIME NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_room_invitation` PRIMARY KEY (`invitation_id`),
  CONSTRAINT `uq_room_invitation_token_hash` UNIQUE (`token_hash`),
  CONSTRAINT `fk_room_invitation_room_id` FOREIGN KEY (`room_id`) REFERENCES `room` (`room_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_room_invitation_created_by_user_id` FOREIGN KEY (`created_by_user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_room_invitation_invited_user_id` FOREIGN KEY (`invited_user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_room_invitation_expiry` CHECK (expires_at > created_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- topic  [Rooms and Membership]
-- Room topic. PREDEFINED topics are managed by a SUPERADMIN and have no creator; CUSTOM topics belong to the user who created them.
--   APP RULE: topic_type = 'CUSTOM' <=> created_by_user_id IS NOT NULL (MySQL forbids CHECK on a column used by a cascading FK).
--   APP RULE: PREDEFINED topic names must be unique (NULL creator is not covered by the UNIQUE key).
--   APP RULE: Only SUPERADMIN can create/edit PREDEFINED topics.
-- ----------------------------------------------------------------------
CREATE TABLE `topic` (
  `topic_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(50) NOT NULL,
  `topic_type` ENUM('PREDEFINED','CUSTOM') NOT NULL,
  `created_by_user_id` BIGINT UNSIGNED NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_topic` PRIMARY KEY (`topic_id`),
  CONSTRAINT `uq_topic_creator_name` UNIQUE (`created_by_user_id`, `name`),
  CONSTRAINT `fk_topic_created_by_user_id` FOREIGN KEY (`created_by_user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- room_topic  [Rooms and Membership]
-- Junction room <-> topic (N:M).
-- ----------------------------------------------------------------------
CREATE TABLE `room_topic` (
  `room_id` BIGINT UNSIGNED NOT NULL,
  `topic_id` BIGINT UNSIGNED NOT NULL,
  CONSTRAINT `pk_room_topic` PRIMARY KEY (`room_id`, `topic_id`),
  INDEX `idx_room_topic_topic` (`topic_id`),
  CONSTRAINT `fk_room_topic_room_id` FOREIGN KEY (`room_id`) REFERENCES `room` (`room_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_room_topic_topic_id` FOREIGN KEY (`topic_id`) REFERENCES `topic` (`topic_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- quiz  [Quiz Management]
-- Quiz owned permanently by its creator. Exists independently of rooms. is_in_library = FALSE marks a quiz created directly from a room, which is not shown in the creator's personal library.
--   APP RULE: Max 15 quizzes per creator.
--   APP RULE: creator_user_id is never updated.
--   APP RULE: Only the creator can delete the quiz and manage its collaborators; creator and collaborators can edit its content.
--   APP RULE: updated_at is refreshed whenever the quiz's questions, options, pairs or media change (ON UPDATE only covers the quiz row itself).
--   APP RULE: total_time_limit_seconds is ONE global time limit for the whole quiz in a live session (not per question).
-- ----------------------------------------------------------------------
CREATE TABLE `quiz` (
  `quiz_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `creator_user_id` BIGINT UNSIGNED NOT NULL,
  `title` VARCHAR(150) NOT NULL,
  `description` TEXT NOT NULL,
  `quiz_status` ENUM('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',
  `is_in_library` BOOLEAN NOT NULL DEFAULT TRUE,
  `total_time_limit_seconds` SMALLINT UNSIGNED NOT NULL DEFAULT 300,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `pk_quiz` PRIMARY KEY (`quiz_id`),
  CONSTRAINT `fk_quiz_creator_user_id` FOREIGN KEY (`creator_user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_quiz_total_time_limit` CHECK (total_time_limit_seconds BETWEEN 60 AND 3600)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- quiz_collaborator  [Quiz Management]
-- Users invited by the quiz owner to edit its content (N:M).
--   APP RULE: The creator cannot be added as a collaborator.
--   APP RULE: Room ADMINs get no implicit collaborator rights.
-- ----------------------------------------------------------------------
CREATE TABLE `quiz_collaborator` (
  `quiz_id` BIGINT UNSIGNED NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `added_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_quiz_collaborator` PRIMARY KEY (`quiz_id`, `user_id`),
  INDEX `idx_quiz_collaborator_user` (`user_id`),
  CONSTRAINT `fk_quiz_collaborator_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_quiz_collaborator_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- room_quiz  [Quiz Management]
-- Quizzes available in a room (N:M). Deleting a row only removes the quiz from that room.
--   APP RULE: Only OWNER/ADMIN of the room can insert/delete rows.
-- ----------------------------------------------------------------------
CREATE TABLE `room_quiz` (
  `room_id` BIGINT UNSIGNED NOT NULL,
  `quiz_id` BIGINT UNSIGNED NOT NULL,
  `added_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_room_quiz` PRIMARY KEY (`room_id`, `quiz_id`),
  INDEX `idx_room_quiz_quiz` (`quiz_id`),
  CONSTRAINT `fk_room_quiz_room_id` FOREIGN KEY (`room_id`) REFERENCES `room` (`room_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_room_quiz_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- question  [Questions and Answers]
-- Question of a quiz with its points. correct_text_answer holds the single accepted answer for OPEN_ANSWER and FILL_IN_THE_BLANK questions.
--   APP RULE: answer_option rows only for MULTIPLE_CHOICE / TRUE_FALSE; matching_pair rows only for MATCHING.
--   APP RULE: MULTIPLE_CHOICE: 2..10 options, exactly one correct.
--   APP RULE: TRUE_FALSE: exactly two options ('TRUE','FALSE'), exactly one correct.
--   APP RULE: MATCHING: at least 2 pairs.
--   APP RULE: A quiz can be PUBLISHED only if every question has a complete correct answer.
--   LEGACY: time_limit_seconds is kept for existing data but no longer used; live sessions use quiz.total_time_limit_seconds.
-- ----------------------------------------------------------------------
CREATE TABLE `question` (
  `question_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `quiz_id` BIGINT UNSIGNED NOT NULL,
  `question_text` TEXT NOT NULL,
  `question_type` ENUM('MULTIPLE_CHOICE','TRUE_FALSE','OPEN_ANSWER','FILL_IN_THE_BLANK','MATCHING') NOT NULL,
  `point_value` INT UNSIGNED NOT NULL DEFAULT 100,
  `time_limit_seconds` SMALLINT UNSIGNED NOT NULL DEFAULT 30,
  `display_order` TINYINT UNSIGNED NOT NULL,
  `correct_text_answer` VARCHAR(255) NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `pk_question` PRIMARY KEY (`question_id`),
  CONSTRAINT `uq_question_quiz_order` UNIQUE (`quiz_id`, `display_order`),
  CONSTRAINT `fk_question_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_question_points` CHECK (point_value > 0),
  CONSTRAINT `chk_question_time_limit` CHECK (time_limit_seconds > 0),
  CONSTRAINT `chk_question_order` CHECK (display_order BETWEEN 1 AND 25),
  CONSTRAINT `chk_question_text_answer` CHECK ((question_type IN ('OPEN_ANSWER','FILL_IN_THE_BLANK') AND correct_text_answer IS NOT NULL) OR (question_type NOT IN ('OPEN_ANSWER','FILL_IN_THE_BLANK') AND correct_text_answer IS NULL))
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- answer_option  [Questions and Answers]
-- Selectable option for MULTIPLE_CHOICE and TRUE_FALSE questions.
--   APP RULE: At least one correct option (the UNIQUE key only guarantees at most one).
-- ----------------------------------------------------------------------
CREATE TABLE `answer_option` (
  `option_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `question_id` BIGINT UNSIGNED NOT NULL,
  `option_text` VARCHAR(255) NOT NULL,
  `is_correct` BOOLEAN NOT NULL DEFAULT FALSE,
  `display_order` TINYINT UNSIGNED NOT NULL,
  `correct_flag` TINYINT GENERATED ALWAYS AS (IF(is_correct, 1, NULL)) STORED NULL,
  CONSTRAINT `pk_answer_option` PRIMARY KEY (`option_id`),
  CONSTRAINT `uq_answer_option_order` UNIQUE (`question_id`, `display_order`),
  CONSTRAINT `uq_answer_option_one_correct` UNIQUE (`question_id`, `correct_flag`),
  CONSTRAINT `fk_answer_option_question_id` FOREIGN KEY (`question_id`) REFERENCES `question` (`question_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_answer_option_order` CHECK (display_order BETWEEN 1 AND 10)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- matching_pair  [Questions and Answers]
-- Correct left/right pair of a MATCHING question.
-- ----------------------------------------------------------------------
CREATE TABLE `matching_pair` (
  `pair_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `question_id` BIGINT UNSIGNED NOT NULL,
  `left_item` VARCHAR(255) NOT NULL,
  `right_item` VARCHAR(255) NOT NULL,
  `display_order` TINYINT UNSIGNED NOT NULL,
  CONSTRAINT `pk_matching_pair` PRIMARY KEY (`pair_id`),
  CONSTRAINT `uq_matching_pair_order` UNIQUE (`question_id`, `display_order`),
  CONSTRAINT `uq_matching_pair_left` UNIQUE (`question_id`, `left_item`),
  CONSTRAINT `uq_matching_pair_right` UNIQUE (`question_id`, `right_item`),
  CONSTRAINT `fk_matching_pair_question_id` FOREIGN KEY (`question_id`) REFERENCES `question` (`question_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `chk_matching_pair_order` CHECK (display_order >= 1)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- question_media  [Questions and Answers]
-- Image, audio or video attached to a question. Only the URL of the file in external cloud storage is stored.
--   APP RULE: Videos are validated/transcoded to max 720p before the URL is stored.
-- ----------------------------------------------------------------------
CREATE TABLE `question_media` (
  `media_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `question_id` BIGINT UNSIGNED NOT NULL,
  `media_type` ENUM('IMAGE','AUDIO','VIDEO') NOT NULL,
  `media_url` VARCHAR(2048) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_question_media` PRIMARY KEY (`media_id`),
  CONSTRAINT `fk_question_media_question_id` FOREIGN KEY (`question_id`) REFERENCES `question` (`question_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- quiz_session  [Game Sessions]
-- One real-time play of a quiz inside a room, started by an OWNER/ADMIN who acts as host.
--   APP RULE: Only OWNER/ADMIN of the room can create a session.
--   APP RULE: Participants are inserted only while status = 'WAITING'; none after IN_PROGRESS.
--   APP RULE: The quiz must be associated with the room (room_quiz) and PUBLISHED.
--   APP RULE: winner_user_id is the first participant who answered every question; NULL when the global time limit expired first or the session was cancelled.
-- ----------------------------------------------------------------------
CREATE TABLE `quiz_session` (
  `session_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `room_id` BIGINT UNSIGNED NOT NULL,
  `quiz_id` BIGINT UNSIGNED NOT NULL,
  `host_user_id` BIGINT UNSIGNED NULL,
  `session_status` ENUM('WAITING','IN_PROGRESS','COMPLETED','CANCELLED') NOT NULL DEFAULT 'WAITING',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` DATETIME NULL,
  `ended_at` DATETIME NULL,
  `winner_user_id` BIGINT UNSIGNED NULL,
  `active_flag` TINYINT GENERATED ALWAYS AS (IF(session_status IN ('WAITING','IN_PROGRESS'), 1, NULL)) STORED NULL,
  CONSTRAINT `pk_quiz_session` PRIMARY KEY (`session_id`),
  CONSTRAINT `uq_quiz_session_one_active` UNIQUE (`room_id`, `active_flag`),
  CONSTRAINT `fk_quiz_session_room_id` FOREIGN KEY (`room_id`) REFERENCES `room` (`room_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_quiz_session_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quiz` (`quiz_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_quiz_session_host_user_id` FOREIGN KEY (`host_user_id`) REFERENCES `user` (`user_id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_quiz_session_winner_user_id` FOREIGN KEY (`winner_user_id`) REFERENCES `user` (`user_id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `chk_quiz_session_times` CHECK (ended_at IS NULL OR started_at IS NULL OR ended_at >= started_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- quiz_attempt  [Game Sessions]
-- Participation of one user in one session; stores the final score.
--   APP RULE: Participant must be a room member when the session starts.
-- ----------------------------------------------------------------------
CREATE TABLE `quiz_attempt` (
  `attempt_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `session_id` BIGINT UNSIGNED NOT NULL,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `total_score` INT UNSIGNED NOT NULL DEFAULT 0,
  `joined_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `disconnected_at` DATETIME NULL,
  `finished_at` DATETIME NULL,
  CONSTRAINT `pk_quiz_attempt` PRIMARY KEY (`attempt_id`),
  CONSTRAINT `uq_quiz_attempt_session_user` UNIQUE (`session_id`, `user_id`),
  INDEX `idx_quiz_attempt_user` (`user_id`),
  CONSTRAINT `fk_quiz_attempt_session_id` FOREIGN KEY (`session_id`) REFERENCES `quiz_session` (`session_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_quiz_attempt_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- user_answer  [Game Sessions]
-- Answer submitted by a participant to one question, with its evaluated correctness and points.
--   APP RULE: question must belong to the session's quiz.
--   APP RULE: By question type: selected_option_id for MULTIPLE_CHOICE / TRUE_FALSE, text_answer for OPEN_ANSWER / FILL_IN_THE_BLANK, user_answer_match rows for MATCHING (not a CHECK: MySQL forbids CHECK on a column used by a SET NULL foreign key).
--   APP RULE: Answers are accepted only within the quiz's global time limit and while the session is IN_PROGRESS.
-- ----------------------------------------------------------------------
CREATE TABLE `user_answer` (
  `user_answer_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `attempt_id` BIGINT UNSIGNED NOT NULL,
  `question_id` BIGINT UNSIGNED NOT NULL,
  `selected_option_id` BIGINT UNSIGNED NULL,
  `text_answer` VARCHAR(255) NULL,
  `is_correct` BOOLEAN NOT NULL DEFAULT FALSE,
  `points_earned` INT UNSIGNED NOT NULL DEFAULT 0,
  `answered_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_user_answer` PRIMARY KEY (`user_answer_id`),
  CONSTRAINT `uq_user_answer_attempt_question` UNIQUE (`attempt_id`, `question_id`),
  CONSTRAINT `fk_user_answer_attempt_id` FOREIGN KEY (`attempt_id`) REFERENCES `quiz_attempt` (`attempt_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_answer_question_id` FOREIGN KEY (`question_id`) REFERENCES `question` (`question_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_answer_selected_option_id` FOREIGN KEY (`selected_option_id`) REFERENCES `answer_option` (`option_id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- user_answer_match  [Game Sessions]
-- For MATCHING questions: which right item the participant matched to each left item. Correct when left_pair_id = selected_right_pair_id.
--   APP RULE: Both pairs must belong to the answered question.
-- ----------------------------------------------------------------------
CREATE TABLE `user_answer_match` (
  `user_answer_id` BIGINT UNSIGNED NOT NULL,
  `left_pair_id` BIGINT UNSIGNED NOT NULL,
  `selected_right_pair_id` BIGINT UNSIGNED NOT NULL,
  CONSTRAINT `pk_user_answer_match` PRIMARY KEY (`user_answer_id`, `left_pair_id`),
  INDEX `idx_user_answer_match_right` (`selected_right_pair_id`),
  CONSTRAINT `fk_user_answer_match_user_answer_id` FOREIGN KEY (`user_answer_id`) REFERENCES `user_answer` (`user_answer_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_answer_match_left_pair_id` FOREIGN KEY (`left_pair_id`) REFERENCES `matching_pair` (`pair_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_user_answer_match_selected_right_pair_id` FOREIGN KEY (`selected_right_pair_id`) REFERENCES `matching_pair` (`pair_id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- translation_cache  [Translation and Vocabulary]
-- Shared translation of one word in one direction (Google Translate) plus the OpenAI contextual explanation. Reused by all users to avoid repeated API calls.
-- ----------------------------------------------------------------------
CREATE TABLE `translation_cache` (
  `translation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `source_word` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_language` ENUM('ENGLISH','KOREAN') NOT NULL,
  `target_language` ENUM('ENGLISH','KOREAN') NOT NULL,
  `translated_word` VARCHAR(255) NOT NULL,
  `contextual_explanation` TEXT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_translation_cache` PRIMARY KEY (`translation_id`),
  CONSTRAINT `uq_translation_cache_word` UNIQUE (`source_word`, `source_language`, `target_language`),
  CONSTRAINT `chk_translation_cache_direction` CHECK (source_language <> target_language)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

-- ----------------------------------------------------------------------
-- saved_word  [Translation and Vocabulary]
-- A user's personal vocabulary entry (also the translation history). Personal data only; the translation itself is shared and read-only.
--   APP RULE: Search and export are queries over saved_word JOIN translation_cache.
-- ----------------------------------------------------------------------
CREATE TABLE `saved_word` (
  `saved_word_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` BIGINT UNSIGNED NOT NULL,
  `translation_id` BIGINT UNSIGNED NOT NULL,
  `personal_note` TEXT NULL,
  `is_favorite` BOOLEAN NOT NULL DEFAULT FALSE,
  `saved_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_looked_up_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT `pk_saved_word` PRIMARY KEY (`saved_word_id`),
  CONSTRAINT `uq_saved_word_user_translation` UNIQUE (`user_id`, `translation_id`),
  CONSTRAINT `fk_saved_word_user_id` FOREIGN KEY (`user_id`) REFERENCES `user` (`user_id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_saved_word_translation_id` FOREIGN KEY (`translation_id`) REFERENCES `translation_cache` (`translation_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;

